CREATE TABLE public.wf_variables (key text NOT NULL, value jsonb DEFAULT '{}'::jsonb NOT NULL, description text, updated_at timestamp with time zone DEFAULT now());
CREATE TABLE public.wf_webhook_endpoints (id uuid DEFAULT gen_random_uuid() NOT NULL, workflow_id uuid NOT NULL, slug text NOT NULL, secret text DEFAULT encode(gen_random_bytes(24), 'hex'::text) NOT NULL, is_active boolean DEFAULT true, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.wf_workflow_versions (id uuid DEFAULT gen_random_uuid() NOT NULL, workflow_id uuid NOT NULL, version_number integer NOT NULL, status text DEFAULT 'draft'::text NOT NULL, definition jsonb DEFAULT '{"edges": [], "nodes": []}'::jsonb NOT NULL, trigger_event_key text, trigger_config jsonb DEFAULT '{}'::jsonb NOT NULL, variables jsonb DEFAULT '{}'::jsonb NOT NULL, change_note text, created_by uuid, created_at timestamp with time zone DEFAULT now(), published_at timestamp with time zone);
CREATE TABLE public.wf_workflows (id uuid DEFAULT gen_random_uuid() NOT NULL, name text NOT NULL, description text, status text DEFAULT 'draft'::text NOT NULL, trigger_event_key text, trigger_config jsonb DEFAULT '{}'::jsonb NOT NULL, is_active boolean DEFAULT true NOT NULL, created_by uuid, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), published_version_id uuid, current_draft_version_id uuid, max_runs_per_hour integer);
CREATE TABLE public.whatsapp_billing_admins (email text NOT NULL, added_by uuid, created_at timestamp with time zone DEFAULT now() NOT NULL, user_id uuid);
CREATE TABLE public.whatsapp_campaign_reports (id uuid DEFAULT gen_random_uuid() NOT NULL, campaign_id uuid, recipient text NOT NULL, status text NOT NULL, error_message text, sent_at timestamp with time zone DEFAULT now(), metadata jsonb DEFAULT '{}'::jsonb);
CREATE TABLE public.whatsapp_campaigns (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid, name text NOT NULL, template_name text, language_code text, total_recipients integer DEFAULT 0, success_count integer DEFAULT 0, fail_count integer DEFAULT 0, status text DEFAULT 'completed'::text, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.whatsapp_subscriptions (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid NOT NULL, ticket_id uuid, status text DEFAULT 'active'::text, billing_cycle text, start_date timestamp with time zone DEFAULT now(), end_date timestamp with time zone NOT NULL, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now(), plan text DEFAULT 'whatsapp'::text NOT NULL, rejection_reason text, is_renewal boolean DEFAULT false NOT NULL, duration_days integer, previous_end_date timestamp with time zone, reviewed_by uuid, reviewed_at timestamp with time zone, payment_method text, payment_reference text, company_id uuid, upgraded_from_subscription_id uuid, upgrade_amount numeric(14,2), price_snapshot jsonb);
CREATE TABLE public.whatsapp_wallet_topup_requests (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid NOT NULL, ticket_id uuid, amount numeric(12,2) NOT NULL, currency text DEFAULT 'EGP'::text NOT NULL, payment_method text, payment_reference text, status text DEFAULT 'pending'::text NOT NULL, rejection_reason text, reviewed_by uuid, reviewed_at timestamp with time zone, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.whatsapp_wallet_transactions (id uuid DEFAULT gen_random_uuid() NOT NULL, wallet_id uuid NOT NULL, user_id uuid NOT NULL, amount numeric(12,2) NOT NULL, balance_before numeric(12,2) NOT NULL, balance_after numeric(12,2) NOT NULL, transaction_type text NOT NULL, description text, ticket_id uuid, performed_by uuid, created_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.whatsapp_wallets (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid NOT NULL, balance numeric(12,2) DEFAULT 0 NOT NULL, currency text DEFAULT 'EGP'::text NOT NULL, low_balance_threshold numeric(12,2) DEFAULT 20 NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.work_hours (id bigint DEFAULT nextval('work_hours_id_seq'::regclass) NOT NULL, day_of_week integer NOT NULL, start_time character varying(5) NOT NULL, end_time character varying(5) NOT NULL, is_work_day boolean DEFAULT true NOT NULL, created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE public.working_hours (id uuid DEFAULT gen_random_uuid() NOT NULL, day_of_week integer NOT NULL, is_working_day boolean DEFAULT true, start_time time without time zone, end_time time without time zone, auto_reply_text text, transfer_to_bot boolean DEFAULT false, updated_at timestamp with time zone DEFAULT now());
